// Generated by gpu_engine.v2e_layout from the oracle pytrees. Do not edit; regenerate with
//   python -m gpu_engine.v2e_layout generate --description <desc.json> --spec <v2e_phases_spec.json> --out <this file>
// and check with `python -m gpu_engine.v2e_layout check`.
//
// Per-lane buffers are row-major [B, ...] as the FFI operands are today; a Leaf<T, D...> gives XLA-exact point access:
//   get(b, i...)      gather as jnp indexing x[rows, i] and lane_index.take do it (every tracker-hook read; jnp wraps and
//                     clamps the index itself and emits a PROMISE_IN_BOUNDS gather, 4,772 of the oracle step's 4,800):
//                     a negative index wraps once (i + dim), then clamps into [0, dim - 1];
//   get_fill(b, i...) gather, fill mode (jnp.take_along_axis, x.at[].get(mode='fill'); the oracle's 28 FILL_OR_DROP
//                     gathers: state.usable_moves 137-148 and legal_actions 159-170, transition 461/465/567/2062,
//                     linked_traps:35, sleep_talk:39-40; none in M1; `python -m gpu_engine.v2e_layout index-census`
//                     lists them): wraps once, then an index still out of range yields the fill value
//                     (NaN for float, INT_MIN for signed, all ones for unsigned, true for bool);
//   set(b, i..., v)   scatter: wraps once, drops the whole write if any index is out of range (returns false), converts
//                     v to T as JAX's _scatter_impl does (integer wrap; float -> int toward zero, saturating, NaN -> 0;
//                     -> bool as != 0);
//   raw(b, i...)      unchecked reference, for proven-in-range fast paths;
//   span(b, i...)     gather-clamped pointer to the sub-block below the given (partial) indices;
//   writable(b, i...) whether a scatter at the given (partial) indices is kept.
// Under V2E_LAYOUT_DEBUG every Leaf and Table carries `uint32_t* dbg` (dbg[0] clamps, dbg[1] drops) the accessors count
// into. Every struct has kDigest (64-bit prefix of sha256 over its path/dtype/shape lines) and kDigestHex; a
// hand-written FFI handler compares kDigest against the `layout_digest` attribute Python passes
// (gpu_engine.v2e_layout.digests) and returns kStaleLayout instead of touching the buffers when they differ.
#pragma once
#include <cstdint>
#include <cstddef>
#include <limits>
#include <type_traits>

#if defined(__CUDACC__)
#define V2E_LAYOUT_HD __host__ __device__ __forceinline__
#else
#define V2E_LAYOUT_HD inline
#endif

namespace v2e_layout {

constexpr uint32_t kStaleLayout = 0x4c41594fu;   // error word: the .so was built for another layout

V2E_LAYOUT_HD void count_event(uint32_t* w) {
#if defined(__CUDA_ARCH__)
  atomicAdd(w, 1u);
#else
  ++*w;
#endif
}

#if defined(V2E_LAYOUT_DEBUG)
#define V2E_LAYOUT_DBG_MEMBER uint32_t* dbg = nullptr;
#define V2E_LAYOUT_COUNT(dbg, slot) do { if (dbg) count_event((dbg) + (slot)); } while (0)
#else
#define V2E_LAYOUT_DBG_MEMBER
#define V2E_LAYOUT_COUNT(dbg, slot) do { (void)(dbg); } while (0)
#endif

// XLA gather point index: wrap once, clamp into [0, n - 1]. Debug slot 0 counts clamps.
V2E_LAYOUT_HD int64_t gather_index(int64_t i, int64_t n, uint32_t* dbg) {
  if (i < 0) i += n;
  if (i < 0) { V2E_LAYOUT_COUNT(dbg, 0); return 0; }
  if (i >= n) { V2E_LAYOUT_COUNT(dbg, 0); return n - 1; }
  return i;
}

// FILL_OR_DROP scatter point index: wrap once; false when still out of range (the caller drops the whole write).
V2E_LAYOUT_HD bool scatter_index(int64_t& i, int64_t n) {
  if (i < 0) i += n;
  return i >= 0 && i < n;
}

// The eight dtypes the oracle pytrees use; every Leaf/Table element type and every scatter update type is one of them.
template <class T> struct is_supported : std::false_type {};
template <> struct is_supported<bool> : std::true_type {};
template <> struct is_supported<int8_t> : std::true_type {};
template <> struct is_supported<uint8_t> : std::true_type {};
template <> struct is_supported<int16_t> : std::true_type {};
template <> struct is_supported<uint16_t> : std::true_type {};
template <> struct is_supported<int32_t> : std::true_type {};
template <> struct is_supported<uint32_t> : std::true_type {};
template <> struct is_supported<float> : std::true_type {};

// jax's default fill value of a fill-mode gather: NaN (float), the minimum (signed), all ones (unsigned), true (bool).
template <class T>
V2E_LAYOUT_HD T fill_value() {
  static_assert(is_supported<T>::value, "unsupported element type");
  if constexpr (std::is_same<T, bool>::value) return true;
  else if constexpr (std::is_floating_point<T>::value) return __builtin_nanf("");
  else if constexpr (std::is_signed<T>::value) return std::numeric_limits<T>::min();
  else return std::numeric_limits<T>::max();
}

// lax.convert_element_type semantics for a scatter update (jax _scatter_impl: promote, scatter, convert back to T).
template <class T, class U>
V2E_LAYOUT_HD T convert(U v) {
  static_assert(is_supported<T>::value, "unsupported operand type");
  static_assert(is_supported<U>::value, "scatter update type must be one of bool, int8..int32, uint8..uint32, float");
  if constexpr (std::is_same<T, U>::value) {
    return v;
  } else if constexpr (std::is_same<T, bool>::value) {
    return v != U(0);
  } else if constexpr (std::is_integral<T>::value && std::is_floating_point<U>::value) {
    if (v != v) return T(0);
    const double hi = static_cast<double>(std::numeric_limits<T>::max());
    const double lo = static_cast<double>(std::numeric_limits<T>::min());
    const double d = static_cast<double>(v);
    if (d >= hi) return std::numeric_limits<T>::max();
    if (d <= lo) return std::numeric_limits<T>::min();
    return static_cast<T>(d);   // toward zero
  } else if constexpr (std::is_integral<T>::value && std::is_same<U, bool>::value) {
    return v ? T(1) : T(0);
  } else if constexpr (std::is_integral<T>::value && std::is_integral<U>::value) {
    using W = typename std::conditional<std::is_signed<U>::value, int64_t, uint64_t>::type;
    return static_cast<T>(static_cast<typename std::make_unsigned<T>::type>(static_cast<W>(v)));   // two's complement wrap
  } else if constexpr (std::is_floating_point<T>::value && std::is_same<U, bool>::value) {
    return v ? T(1) : T(0);
  } else if constexpr (std::is_floating_point<T>::value && std::is_integral<U>::value) {
#if defined(__CUDA_ARCH__)
    if constexpr (sizeof(U) >= 4 && std::is_signed<U>::value) return __int2float_rn(static_cast<int32_t>(v));
    else if constexpr (sizeof(U) >= 4) return __uint2float_rn(static_cast<uint32_t>(v));
    else return static_cast<T>(v);
#else
    return static_cast<T>(v);   // round to nearest even, as the device intrinsics
#endif
  } else {
    return static_cast<T>(v);
  }
}

// ---- per-lane leaves --------------------------------------------------------------------------
// Common storage: row-major [B, D...]; `p` points at lane 0; kPerLane elements per lane.
template <class T, int... D>
struct LeafBase {
  static constexpr int kRank = sizeof...(D);
  static constexpr int64_t kPerLane = (int64_t(1) * ... * int64_t(D));
  T* p = nullptr;
  int64_t lanes = 0;
  V2E_LAYOUT_DBG_MEMBER
  V2E_LAYOUT_HD T* lane(int64_t b) const { return p + b * kPerLane; }
  V2E_LAYOUT_HD uint32_t* counters() const {
#if defined(V2E_LAYOUT_DEBUG)
    return dbg;
#else
    return nullptr;
#endif
  }
};

template <class T, int... D> struct Leaf;

template <class T>
struct Leaf<T> : LeafBase<T> {
  using Base = LeafBase<T>;
  using Base::p; using Base::lanes; using Base::kPerLane; using Base::kRank;
  using value_type = T;
  V2E_LAYOUT_HD static int64_t offset(int64_t b) { return b * kPerLane + 0; }
  V2E_LAYOUT_HD T& raw(int64_t b) const { return p[offset(b)]; }
  V2E_LAYOUT_HD T get(int64_t b) const { return p[offset(b)]; }
  V2E_LAYOUT_HD T get_fill(int64_t b) const {
    return p[offset(b)];
  }
  template <class U>
  V2E_LAYOUT_HD bool set(int64_t b, U v) const {
    static_assert(is_supported<U>::value, "scatter update type must be one of bool, int8..int32, uint8..uint32, float");
    p[offset(b)] = convert<T>(v);
    return true;
  }
};

template <class T, int D0>
struct Leaf<T, D0> : LeafBase<T, D0> {
  using Base = LeafBase<T, D0>;
  using Base::p; using Base::lanes; using Base::kPerLane; using Base::kRank;
  using value_type = T;
  static constexpr int kDims[1] = {D0};
  V2E_LAYOUT_HD static int64_t offset(int64_t b, int64_t i0) { return b * kPerLane + i0; }
  V2E_LAYOUT_HD T& raw(int64_t b, int64_t i0) const { return p[offset(b, i0)]; }
  V2E_LAYOUT_HD T get(int64_t b, int64_t i0) const { return p[offset(b, gather_index(i0, D0, this->counters()))]; }
  V2E_LAYOUT_HD T get_fill(int64_t b, int64_t i0) const {
    bool ok = true;
    ok = scatter_index(i0, D0) && ok;
    if (!ok) { V2E_LAYOUT_COUNT(this->counters(), 0); return fill_value<T>(); }
    return p[offset(b, i0)];
  }
  template <class U>
  V2E_LAYOUT_HD bool set(int64_t b, int64_t i0, U v) const {
    static_assert(is_supported<U>::value, "scatter update type must be one of bool, int8..int32, uint8..uint32, float");
    bool ok = true;
    ok = scatter_index(i0, D0) && ok;
    if (!ok) { V2E_LAYOUT_COUNT(this->counters(), 1); return false; }
    p[offset(b, i0)] = convert<T>(v);
    return true;
  }
  V2E_LAYOUT_HD T* span(int64_t b) const { return p + offset(b, 0); }
  V2E_LAYOUT_HD bool writable(int64_t b) const { (void)b; return true; }
};

template <class T, int D0, int D1>
struct Leaf<T, D0, D1> : LeafBase<T, D0, D1> {
  using Base = LeafBase<T, D0, D1>;
  using Base::p; using Base::lanes; using Base::kPerLane; using Base::kRank;
  using value_type = T;
  static constexpr int kDims[2] = {D0, D1};
  V2E_LAYOUT_HD static int64_t offset(int64_t b, int64_t i0, int64_t i1) { return b * kPerLane + i0 * D1 + i1; }
  V2E_LAYOUT_HD T& raw(int64_t b, int64_t i0, int64_t i1) const { return p[offset(b, i0, i1)]; }
  V2E_LAYOUT_HD T get(int64_t b, int64_t i0, int64_t i1) const { return p[offset(b, gather_index(i0, D0, this->counters()), gather_index(i1, D1, this->counters()))]; }
  V2E_LAYOUT_HD T get_fill(int64_t b, int64_t i0, int64_t i1) const {
    bool ok = true;
    ok = scatter_index(i0, D0) && ok;
    ok = scatter_index(i1, D1) && ok;
    if (!ok) { V2E_LAYOUT_COUNT(this->counters(), 0); return fill_value<T>(); }
    return p[offset(b, i0, i1)];
  }
  template <class U>
  V2E_LAYOUT_HD bool set(int64_t b, int64_t i0, int64_t i1, U v) const {
    static_assert(is_supported<U>::value, "scatter update type must be one of bool, int8..int32, uint8..uint32, float");
    bool ok = true;
    ok = scatter_index(i0, D0) && ok;
    ok = scatter_index(i1, D1) && ok;
    if (!ok) { V2E_LAYOUT_COUNT(this->counters(), 1); return false; }
    p[offset(b, i0, i1)] = convert<T>(v);
    return true;
  }
  V2E_LAYOUT_HD T* span(int64_t b) const { return p + offset(b, 0, 0); }
  V2E_LAYOUT_HD bool writable(int64_t b) const { (void)b; return true; }
  V2E_LAYOUT_HD T* span(int64_t b, int64_t i0) const { return p + offset(b, gather_index(i0, D0, this->counters()), 0); }
  V2E_LAYOUT_HD bool writable(int64_t b, int64_t i0) const { (void)b; return scatter_index(i0, D0); }
};

template <class T, int D0, int D1, int D2>
struct Leaf<T, D0, D1, D2> : LeafBase<T, D0, D1, D2> {
  using Base = LeafBase<T, D0, D1, D2>;
  using Base::p; using Base::lanes; using Base::kPerLane; using Base::kRank;
  using value_type = T;
  static constexpr int kDims[3] = {D0, D1, D2};
  V2E_LAYOUT_HD static int64_t offset(int64_t b, int64_t i0, int64_t i1, int64_t i2) { return b * kPerLane + i0 * D1 * D2 + i1 * D2 + i2; }
  V2E_LAYOUT_HD T& raw(int64_t b, int64_t i0, int64_t i1, int64_t i2) const { return p[offset(b, i0, i1, i2)]; }
  V2E_LAYOUT_HD T get(int64_t b, int64_t i0, int64_t i1, int64_t i2) const { return p[offset(b, gather_index(i0, D0, this->counters()), gather_index(i1, D1, this->counters()), gather_index(i2, D2, this->counters()))]; }
  V2E_LAYOUT_HD T get_fill(int64_t b, int64_t i0, int64_t i1, int64_t i2) const {
    bool ok = true;
    ok = scatter_index(i0, D0) && ok;
    ok = scatter_index(i1, D1) && ok;
    ok = scatter_index(i2, D2) && ok;
    if (!ok) { V2E_LAYOUT_COUNT(this->counters(), 0); return fill_value<T>(); }
    return p[offset(b, i0, i1, i2)];
  }
  template <class U>
  V2E_LAYOUT_HD bool set(int64_t b, int64_t i0, int64_t i1, int64_t i2, U v) const {
    static_assert(is_supported<U>::value, "scatter update type must be one of bool, int8..int32, uint8..uint32, float");
    bool ok = true;
    ok = scatter_index(i0, D0) && ok;
    ok = scatter_index(i1, D1) && ok;
    ok = scatter_index(i2, D2) && ok;
    if (!ok) { V2E_LAYOUT_COUNT(this->counters(), 1); return false; }
    p[offset(b, i0, i1, i2)] = convert<T>(v);
    return true;
  }
  V2E_LAYOUT_HD T* span(int64_t b) const { return p + offset(b, 0, 0, 0); }
  V2E_LAYOUT_HD bool writable(int64_t b) const { (void)b; return true; }
  V2E_LAYOUT_HD T* span(int64_t b, int64_t i0) const { return p + offset(b, gather_index(i0, D0, this->counters()), 0, 0); }
  V2E_LAYOUT_HD bool writable(int64_t b, int64_t i0) const { (void)b; return scatter_index(i0, D0); }
  V2E_LAYOUT_HD T* span(int64_t b, int64_t i0, int64_t i1) const { return p + offset(b, gather_index(i0, D0, this->counters()), gather_index(i1, D1, this->counters()), 0); }
  V2E_LAYOUT_HD bool writable(int64_t b, int64_t i0, int64_t i1) const { (void)b; return scatter_index(i0, D0) && scatter_index(i1, D1); }
};

template <class T, int D0, int D1, int D2, int D3>
struct Leaf<T, D0, D1, D2, D3> : LeafBase<T, D0, D1, D2, D3> {
  using Base = LeafBase<T, D0, D1, D2, D3>;
  using Base::p; using Base::lanes; using Base::kPerLane; using Base::kRank;
  using value_type = T;
  static constexpr int kDims[4] = {D0, D1, D2, D3};
  V2E_LAYOUT_HD static int64_t offset(int64_t b, int64_t i0, int64_t i1, int64_t i2, int64_t i3) { return b * kPerLane + i0 * D1 * D2 * D3 + i1 * D2 * D3 + i2 * D3 + i3; }
  V2E_LAYOUT_HD T& raw(int64_t b, int64_t i0, int64_t i1, int64_t i2, int64_t i3) const { return p[offset(b, i0, i1, i2, i3)]; }
  V2E_LAYOUT_HD T get(int64_t b, int64_t i0, int64_t i1, int64_t i2, int64_t i3) const { return p[offset(b, gather_index(i0, D0, this->counters()), gather_index(i1, D1, this->counters()), gather_index(i2, D2, this->counters()), gather_index(i3, D3, this->counters()))]; }
  V2E_LAYOUT_HD T get_fill(int64_t b, int64_t i0, int64_t i1, int64_t i2, int64_t i3) const {
    bool ok = true;
    ok = scatter_index(i0, D0) && ok;
    ok = scatter_index(i1, D1) && ok;
    ok = scatter_index(i2, D2) && ok;
    ok = scatter_index(i3, D3) && ok;
    if (!ok) { V2E_LAYOUT_COUNT(this->counters(), 0); return fill_value<T>(); }
    return p[offset(b, i0, i1, i2, i3)];
  }
  template <class U>
  V2E_LAYOUT_HD bool set(int64_t b, int64_t i0, int64_t i1, int64_t i2, int64_t i3, U v) const {
    static_assert(is_supported<U>::value, "scatter update type must be one of bool, int8..int32, uint8..uint32, float");
    bool ok = true;
    ok = scatter_index(i0, D0) && ok;
    ok = scatter_index(i1, D1) && ok;
    ok = scatter_index(i2, D2) && ok;
    ok = scatter_index(i3, D3) && ok;
    if (!ok) { V2E_LAYOUT_COUNT(this->counters(), 1); return false; }
    p[offset(b, i0, i1, i2, i3)] = convert<T>(v);
    return true;
  }
  V2E_LAYOUT_HD T* span(int64_t b) const { return p + offset(b, 0, 0, 0, 0); }
  V2E_LAYOUT_HD bool writable(int64_t b) const { (void)b; return true; }
  V2E_LAYOUT_HD T* span(int64_t b, int64_t i0) const { return p + offset(b, gather_index(i0, D0, this->counters()), 0, 0, 0); }
  V2E_LAYOUT_HD bool writable(int64_t b, int64_t i0) const { (void)b; return scatter_index(i0, D0); }
  V2E_LAYOUT_HD T* span(int64_t b, int64_t i0, int64_t i1) const { return p + offset(b, gather_index(i0, D0, this->counters()), gather_index(i1, D1, this->counters()), 0, 0); }
  V2E_LAYOUT_HD bool writable(int64_t b, int64_t i0, int64_t i1) const { (void)b; return scatter_index(i0, D0) && scatter_index(i1, D1); }
  V2E_LAYOUT_HD T* span(int64_t b, int64_t i0, int64_t i1, int64_t i2) const { return p + offset(b, gather_index(i0, D0, this->counters()), gather_index(i1, D1, this->counters()), gather_index(i2, D2, this->counters()), 0); }
  V2E_LAYOUT_HD bool writable(int64_t b, int64_t i0, int64_t i1, int64_t i2) const { (void)b; return scatter_index(i0, D0) && scatter_index(i1, D1) && scatter_index(i2, D2); }
};

// ---- tables -----------------------------------------------------------------------------------
// A table array (no lane axis), row-major, read through the same gather semantics; constant for every lane.
template <class T, int... D>
struct Table {
  static constexpr int kRank = sizeof...(D);
  static constexpr int64_t kSize = (int64_t(1) * ... * int64_t(D));
  const T* p = nullptr;
  V2E_LAYOUT_DBG_MEMBER
  V2E_LAYOUT_HD uint32_t* counters() const {
#if defined(V2E_LAYOUT_DEBUG)
    return dbg;
#else
    return nullptr;
#endif
  }
  template <int R = kRank, typename std::enable_if<R == 0, int>::type = 0>
  V2E_LAYOUT_HD T get() const { return p[0]; }
  template <int R = kRank, typename std::enable_if<R == 0, int>::type = 0>
  V2E_LAYOUT_HD T raw() const { return p[0]; }
  template <int R = kRank, typename std::enable_if<R == 1, int>::type = 0>
  V2E_LAYOUT_HD T get(int64_t i0) const {
    constexpr int dims[kRank] = {D...};
    i0 = gather_index(i0, dims[0], this->counters());
    return p[i0];
  }
  template <int R = kRank, typename std::enable_if<R == 1, int>::type = 0>
  V2E_LAYOUT_HD T raw(int64_t i0) const {
    constexpr int dims[kRank] = {D...};
    return p[i0];
  }
  template <int R = kRank, typename std::enable_if<R == 2, int>::type = 0>
  V2E_LAYOUT_HD T get(int64_t i0, int64_t i1) const {
    constexpr int dims[kRank] = {D...};
    i0 = gather_index(i0, dims[0], this->counters());
    i1 = gather_index(i1, dims[1], this->counters());
    return p[i0 * dims[1] + i1];
  }
  template <int R = kRank, typename std::enable_if<R == 2, int>::type = 0>
  V2E_LAYOUT_HD T raw(int64_t i0, int64_t i1) const {
    constexpr int dims[kRank] = {D...};
    return p[i0 * dims[1] + i1];
  }
  template <int R = kRank, typename std::enable_if<R == 3, int>::type = 0>
  V2E_LAYOUT_HD T get(int64_t i0, int64_t i1, int64_t i2) const {
    constexpr int dims[kRank] = {D...};
    i0 = gather_index(i0, dims[0], this->counters());
    i1 = gather_index(i1, dims[1], this->counters());
    i2 = gather_index(i2, dims[2], this->counters());
    return p[i0 * dims[1] * dims[2] + i1 * dims[2] + i2];
  }
  template <int R = kRank, typename std::enable_if<R == 3, int>::type = 0>
  V2E_LAYOUT_HD T raw(int64_t i0, int64_t i1, int64_t i2) const {
    constexpr int dims[kRank] = {D...};
    return p[i0 * dims[1] * dims[2] + i1 * dims[2] + i2];
  }
  template <int R = kRank, typename std::enable_if<R == 4, int>::type = 0>
  V2E_LAYOUT_HD T get(int64_t i0, int64_t i1, int64_t i2, int64_t i3) const {
    constexpr int dims[kRank] = {D...};
    i0 = gather_index(i0, dims[0], this->counters());
    i1 = gather_index(i1, dims[1], this->counters());
    i2 = gather_index(i2, dims[2], this->counters());
    i3 = gather_index(i3, dims[3], this->counters());
    return p[i0 * dims[1] * dims[2] * dims[3] + i1 * dims[2] * dims[3] + i2 * dims[3] + i3];
  }
  template <int R = kRank, typename std::enable_if<R == 4, int>::type = 0>
  V2E_LAYOUT_HD T raw(int64_t i0, int64_t i1, int64_t i2, int64_t i3) const {
    constexpr int dims[kRank] = {D...};
    return p[i0 * dims[1] * dims[2] * dims[3] + i1 * dims[2] * dims[3] + i2 * dims[3] + i3];
  }
};

